#include "jp8000.h"
#include "firmware_host.hpp"
#include "controls.inc"
#include <fstream>
#include <cstring>
struct jp8000 { std::unique_ptr<Host> host; std::string error; std::vector<uint8_t> coherentState; };
static std::vector<uint8_t> readFile(const char* p,size_t required){if(!p)throw std::runtime_error("missing input path");std::ifstream f(p,std::ios::binary);std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});if(b.size()!=required)throw std::runtime_error("incorrect firmware or baseline RAM size");return b;}
template<class F> static int guard(jp8000_t*h,F f){if(!h)return-1;try{f(*h->host);h->error.clear();return 0;}catch(const std::exception&e){h->error=e.what();return-1;}}
static void refresh(Host& h,uint64_t delay=SampleRate/10){h.nextRefreshFrame=h.framePosition+delay;}
static bool syncing(const Host& h){return h.refreshInFlight||h.nextRefreshFrame!=Host::NoRefresh;}
static void queue(Host& h,synthLib::SysexBuffer bytes){if(h.pending.size()>=500)throw std::runtime_error("firmware MIDI queue full");Event e(synthLib::MidiEventSource::Editor);e.sysex=std::move(bytes);h.pending.push_back(std::move(e));}
extern "C" {
jp8000_t* jp8000_create(const char*rom,const char*ram,char*error,size_t cap){try{NativeCreateParams p;p.romData=readFile(rom,524288);p.romName="jp8000_v1.05.bin";auto data=readFile(ram,262144);auto h=std::make_unique<jp8000>();h->host=std::make_unique<Host>(p,data);h->host->device.getState(h->coherentState,0);if(error&&cap)error[0]=0;return h.release();}catch(const std::exception&e){if(error&&cap){std::strncpy(error,e.what(),cap-1);error[cap-1]=0;}return nullptr;}}
void jp8000_destroy(jp8000_t*h){delete h;}
uint32_t jp8000_native_sample_rate(void){return SampleRate;}
int jp8000_ready(jp8000_t*h){return h&&h->host->booted;}
int jp8000_stats(jp8000_t*h,jp8000_stats_t*out){return guard(h,[&](Host&v){if(!out)throw std::runtime_error("null stats output");*out={};v.device.getJe8086().forEachEsp([&](const auto&chip){const auto s=chip.statistics();out->aot_hits+=s.native;out->aot_fallbacks+=s.interpreted;});out->frame_position=v.framePosition;out->ready=v.booted;out->state_syncing=syncing(v);});}
int jp8000_render(jp8000_t*h,float*l,float*r,uint32_t n){return guard(h,[&](Host&v){if(!l||!r||!n||n>8192)throw std::runtime_error("invalid render buffers or frame count");v.command({{"op","render"},{"frames",n},{"_native",true}});for(size_t i=0;i<n;++i){l[i]=v.lastPcm[i*2];r[i]=v.lastPcm[i*2+1];}});}
int jp8000_midi(jp8000_t*h,uint8_t status,uint8_t a,uint8_t b,uint32_t offset){return guard(h,[&](Host&v){const bool channel=status>=0x80&&status<=0xef;const bool system=status==0xf1||status==0xf2||status==0xf3||status==0xf6||status==0xf8||status==0xfa||status==0xfb||status==0xfc||status==0xfe;const auto length=synthLib::MidiBufferParser::lengthFromStatusByte(status);if((!channel&&!system)||(length>1&&a>127)||(length>2&&b>127)||offset>88200||v.pending.size()>=500)throw std::runtime_error("invalid MIDI or queue full");Event e(synthLib::MidiEventSource::Host);e.a=status;e.b=length>1?a:0;e.c=length>2?b:0;e.offset=offset;v.pending.push_back(e);if((status&0xf0)==0xc0)refresh(v,offset+SampleRate/3);});}
int jp8000_parameter(jp8000_t*h,jp8000_scope scope,uint32_t wire,uint32_t value,uint32_t width){return guard(h,[&](Host&v){if(scope<0||scope>5)throw std::runtime_error("unknown parameter scope");const unsigned group=scope<2?0:scope<4?1:scope==4?2:3;const Control*found=nullptr;for(const auto&c:Controls)if(c.scope==group&&c.wire==wire)found=&c;if(!found||found->width!=width||value<found->min||value>found->max)throw std::runtime_error("unsupported parameter, width or value");constexpr uint32_t base[]={0x01004000,0x01004200,0x01001000,0x01001100,0x01000000,0};auto message=jeLib::State::createHeader(jeLib::SysexByte::CommandIdDataSet1,jeLib::SysexByte::DeviceIdDefault,jeLib::State::toAddress(base[scope]|wire));jeLib::State::addParameter(message,width==2,int(value));jeLib::State::createFooter(message);queue(v,std::move(message));refresh(v);});}
int jp8000_factory_patch(jp8000_t*h,uint32_t index,uint32_t part){return guard(h,[&](Host&v){if(part>1||index>=128)throw std::runtime_error("invalid patch or part");v.command({{"op","preset"},{"index",index},{"part",part?"lower":"upper"}});refresh(v,SampleRate/3);});}
int jp8000_factory_performance(jp8000_t*h,uint32_t index){return guard(h,[&](Host&v){if(index>=64||v.presets.size()<3)throw std::runtime_error("invalid performance");if(v.pending.size()>490)throw std::runtime_error("firmware MIDI queue full");for(auto message:v.presets.at(2).at(index)){const auto address=0x01000000u|(jeLib::State::getAddress(message)&0xffffu);jeLib::State::setAddress(message,address);jeLib::State::updateChecksum(message);queue(v,std::move(message));}refresh(v,SampleRate/2);});}
int jp8000_panel(jp8000_t*h,uint32_t button,int down){return guard(h,[&](Host&v){v.command({{"op","panel"},{"button",button},{"down",down!=0}});});}
int jp8000_panic(jp8000_t*h){return guard(h,[&](Host&v){v.command({{"op","panic"}});});}
const char*jp8000_last_error(jp8000_t*h){return h?h->error.c_str():"null JP-8000 handle";}
size_t jp8000_snapshot_json(jp8000_t*h,char*out,size_t cap){if(!h)return 0;try{auto&v=*h->host;auto j=v.status();j["ready"]=v.booted;j["state_complete"]=v.stateComplete();j["part"]=0;if(!syncing(v)&&v.stateComplete())v.device.getState(h->coherentState,0);const auto& bytes=h->coherentState;std::map<uint32_t,std::vector<uint8_t>> blocks;if(!bytes.empty()){for(size_t begin=0;begin<bytes.size();){auto end=std::find(bytes.begin()+begin,bytes.end(),uint8_t(0xf7));if(end==bytes.end())break;synthLib::SysexBuffer msg(bytes.begin()+begin,end+1);if(msg.size()>=12)blocks[jeLib::State::getAddress(msg)]={msg.begin()+10,msg.end()-2};begin=size_t(end-bytes.begin())+1;}}
 j["midi_channels"]=Json::array();for(unsigned part=0;part<2;++part){Json params=Json::object();const uint32_t bases[]={part?0x01004200u:0x01004000u,part?0x01001100u:0x01001000u,0x01000000u,0};for(const auto&c:Controls){auto it=blocks.find(bases[c.scope]);if(it==blocks.end()||c.linear+c.width>it->second.size())continue;unsigned value=0;for(unsigned b=0;b<c.width;++b)value=(value<<7)|it->second[c.linear+b];params[std::to_string(c.scope*1000+c.wire)]=value;}j[part?"params_lower":"params_upper"]=params;if(!part)j["params"]=params;auto patch=blocks.find(bases[0]);std::string name;if(patch!=blocks.end())for(size_t i=0;i<16&&i<patch->second.size();++i){auto c=patch->second[i];name.push_back(c>=32&&c<127?char(c):' ');}while(!name.empty()&&name.back()==' ')name.pop_back();j[part?"lower_name":"upper_name"]=name;j["midi_channels"].push_back(params.contains("1002")?params["1002"]:Json(nullptr));}
 auto performance=blocks.find(0x01000000);std::string performanceName;if(performance!=blocks.end())for(size_t i=0;i<16&&i<performance->second.size();++i){auto c=performance->second[i];performanceName.push_back(c>=32&&c<127?char(c):' ');}while(!performanceName.empty()&&performanceName.back()==' ')performanceName.pop_back();j["performance_name"]=performanceName;
 jp8000_stats_t s{};jp8000_stats(h,&s);j["aot_hits"]=s.aot_hits;j["aot_fallbacks"]=s.aot_fallbacks;j["engine"]= "static ARM64 ESP kernels with canonical interpreter fallback";const auto text=j.dump();const size_t need=text.size()+1;if(out&&cap>=need)std::memcpy(out,text.c_str(),need);return need;}catch(const std::exception&e){h->error=e.what();return 0;}}
size_t jp8000_save_state(jp8000_t*h,uint8_t*out,size_t cap){if(!h)return 0;try{auto&v=*h->host;if(syncing(v)||!v.pending.empty()||!v.refreshError.empty()||!v.stateComplete())throw std::runtime_error("firmware state readback is not complete");std::vector<uint8_t>b;if(!v.device.getState(b,0))throw std::runtime_error("firmware state missing");if(out&&cap>=b.size())std::memcpy(out,b.data(),b.size());return b.size();}catch(const std::exception&e){h->error=e.what();return 0;}}
int jp8000_load_state(jp8000_t*h,const uint8_t*b,size_t n){return guard(h,[&](Host&v){if(!b||!n||n>65536)throw std::runtime_error("invalid state buffer");std::vector<uint8_t>bytes(b,b+n);v.command({{"op","load_state"},{"bytes",bytes}});refresh(v,SampleRate);});}
}
